    database.run(`CREATE TRIGGER calendar_series_child_readiness BEFORE UPDATE ON ${t.state} WHEN NEW.id IS NOT OLD.id OR NEW.version<>OLD.version OR OLD.ranges_ready<>0 OR NEW.ranges_ready<>1 OR EXISTS(SELECT 1 FROM calendar_series s WHERE s.published_publication_id IS NOT NULL AND NOT ${qualified()}) BEGIN SELECT RAISE(ABORT,'Private child range promotion is incomplete'); END`);
