    for (const [table,column] of [[t.heads,'child_count'],[t.resources,'resource_count'],[t.directory,'directory_count']] as const) database.run(`CREATE TRIGGER ${table}_child_view_phase AFTER UPDATE OF phase ON ${t.views} WHEN NEW.phase<>OLD.phase BEGIN UPDATE ${t.capacity} SET current_count=current_count+(CASE WHEN NEW.phase='current' THEN NEW.${column} ELSE 0 END)-(CASE WHEN OLD.phase='current' THEN NEW.${column} ELSE 0 END),pending_count=pending_count+(CASE WHEN NEW.phase IN ('pending','ready') THEN NEW.${column} ELSE 0 END)-(CASE WHEN OLD.phase IN ('pending','ready') THEN NEW.${column} ELSE 0 END),retiring_count=retiring_count+(CASE WHEN NEW.phase IN ('retiring','aborted') THEN NEW.${column} ELSE 0 END)-(CASE WHEN OLD.phase IN ('retiring','aborted') THEN NEW.${column} ELSE 0 END) WHERE id='${table}'; END`);
    for (const [table,column] of [[t.heads,'candidate_count'],[t.resources,'resource_count']] as const) database.run(`CREATE TRIGGER ${table}_child_native_phase AFTER UPDATE OF phase ON ${native.runState} WHEN NEW.phase<>OLD.phase AND EXISTS(SELECT 1 FROM ${t.batches} b JOIN ${t.views} v ON v.id=b.view_id WHERE b.run_id=NEW.id AND b.origin_kind='native21' AND b.phase='begin' AND v.phase='current') BEGIN UPDATE ${t.capacity} SET current_count=current_count+(CASE WHEN NEW.phase='current' THEN NEW.${column} ELSE 0 END)-(CASE WHEN OLD.phase='current' THEN NEW.${column} ELSE 0 END),pending_count=pending_count+(CASE WHEN NEW.phase='pending' THEN NEW.${column} ELSE 0 END)-(CASE WHEN OLD.phase='pending' THEN NEW.${column} ELSE 0 END),retiring_count=retiring_count+(CASE WHEN NEW.phase='retiring' THEN NEW.${column} ELSE 0 END)-(CASE WHEN OLD.phase='retiring' THEN NEW.${column} ELSE 0 END) WHERE id='${table}'; END`);
    const nativeHead = `EXISTS(SELECT 1 FROM ${native.versions} v JOIN ${native.runs} r ON r.id=v.run_id JOIN ${native.occurrences} o ON o.id=v.occurrence_id JOIN ${t.views} w ON w.id=NEW.view_id JOIN calendar_series s ON s.id=w.series_id WHERE v.id=NEW.native_version_id AND v.id=NEW.version_id AND v.scope_id=NEW.scope_id AND v.series_id=NEW.series_id AND r.id=NEW.native_run_id AND r.series_id=w.series_id AND r.scope_id=w.scope_id AND o.id=NEW.occurrence_id AND o.appointment_id=NEW.appointment_id AND o.logical_segment_id=NEW.logical_segment_id AND o.nominal_key=NEW.nominal_key AND s.created_by=NEW.created_by AND NEW.child_revision=1 AND NEW.selection_revision=1 AND NEW.child_exception_revision=0 AND NEW.status='confirmed' AND NEW.variant_version_id IS NULL AND v.resource_ids_json=NEW.authority_resource_ids_json AND v.resource_digest=NEW.resource_digest AND v.binding_digest=NEW.binding_digest AND v.start_ms=NEW.start_ms AND v.end_ms=NEW.end_ms AND v.occupied_from_ms=NEW.occupied_from_ms AND v.occupied_until_ms=NEW.occupied_until_ms)`;
