    database.run(`CREATE TRIGGER calendar_series_child_head_parent BEFORE INSERT ON ${t.heads} WHEN NEW.appointment_id<>NEW.occurrence_id OR NOT (${vector('NEW.authority_resource_ids_json')}) OR NOT EXISTS(SELECT 1 FROM ${t.views} WHERE id=NEW.view_id AND scope_id=NEW.scope_id AND series_id=NEW.series_id AND phase IN ('pending','ready','current')) OR NEW.created_batch_id<>NEW.last_batch_id OR NOT ((NEW.origin_kind='native21' AND ${nativeHead}) OR (NEW.origin_kind='variant22' AND ${variantHead})) BEGIN SELECT RAISE(ABORT,'Private selected child origin is inconsistent'); END`);
