    database.run(`CREATE TRIGGER calendar_series_child_directory_parent BEFORE INSERT ON ${t.directory} WHEN NOT EXISTS(SELECT 1 FROM ${t.views} v JOIN _calendar_series_grants a ON a.id=v.legacy_grant_id JOIN calendar_resources r ON r.scope_id=v.scope_id AND r.id=NEW.resource_id WHERE v.id=NEW.view_id AND v.scope_id=NEW.scope_id AND v.series_id=NEW.series_id AND v.phase IN ('pending','ready','current') AND EXISTS(SELECT 1 FROM json_each(a.resource_ids_json) WHERE value=NEW.resource_id)) BEGIN SELECT RAISE(ABORT,'Private child resource directory is inconsistent'); END`);
