    database.run(`CREATE TRIGGER calendar_series_child_change_cas BEFORE UPDATE ON ${t.changes} WHEN ${changeIdentity} OR NEW.revision<>OLD.revision+1 OR OLD.state IN ('published','aborted') OR EXISTS(SELECT 1 FROM ${t.batches} WHERE id=NEW.last_batch_id) OR (NEW.state='published' AND NOT EXISTS(SELECT 1 FROM ${t.publications} WHERE id=NEW.publication_id AND change_id=NEW.id)) OR (NEW.state<>'published' AND NEW.publication_id IS NOT NULL) BEGIN SELECT RAISE(ABORT,'Private child edit CAS is inconsistent'); END`);
    database.run(`CREATE TRIGGER calendar_series_child_old_member_parent BEFORE INSERT ON ${t.oldMembers} WHEN NOT EXISTS(SELECT 1 FROM ${t.changes} p JOIN ${t.heads} h ON h.view_id=p.view_id AND h.appointment_id=p.appointment_id WHERE p.id=NEW.change_id AND p.scope_id=NEW.scope_id AND p.view_id=NEW.view_id AND p.appointment_id=NEW.appointment_id AND p.state='preparing' AND h.version_id=NEW.version_id AND h.child_revision=NEW.child_revision AND h.selection_revision=NEW.selection_revision AND h.child_exception_revision=NEW.child_exception_revision AND h.resource_digest=NEW.resource_digest AND p.expected_version_id=h.version_id AND p.expected_child_revision=h.child_revision AND p.expected_selection_revision=h.selection_revision AND p.expected_exception_revision=h.child_exception_revision) BEGIN SELECT RAISE(ABORT,'Private reviewed child exclusion is inconsistent'); END`);
